    protected void insertOrderHeader(PurchPurchaseOrderHeader _purchaseOrderHeader)
    {
        PurchTable purchTable = PurchTable::find(_purchaseOrderHeader.PurchId);

        // Should pick up details from journal, not from PO.

        _purchaseOrderHeader.METVersionText             = "Version 1";
        _purchaseOrderHeader.METOrderToDetails          = "ABN 121721\nVendor number / Sub: 984394834/1";
        _purchaseOrderHeader.METDeliveryDate            = purchTable.DeliveryDate;
        _purchaseOrderHeader.METSpecialInstructions     = '-Special instructions-';
        _purchaseOrderHeader.METContactName             = 'Contact name';
        _purchaseOrderHeader.METContactEmail            = 'contact@metcash.com';
        _purchaseOrderHeader.METContactPhone            = '0450 000 000';
        _purchaseOrderHeader.METReceivingDockDetails    = '0450 011 011';
        _purchaseOrderHeader.METLegendText              = vendFormletterParameters::find().METPurchOrderReportLegendText;

        next insertOrderHeader(_purchaseOrderHeader);
    }

    protected void insertOrderLine(PurchPurchaseOrderTmp _purchaseOrderTmp)
    {
        PurchLine purchLine = PurchLine::findInventTransId(_purchaseOrderTmp.PurchLineInventTransId);

        _purchaseOrderTmp.METGTIN                   = '[gtin]';
        _purchaseOrderTmp.METTi                     = 3;
        _purchaseOrderTmp.METHi                     = 5;
        _purchaseOrderTmp.METMLOR                   = 99;
        _purchaseOrderTmp.METPalletQty              = 66;
        _purchaseOrderTmp.METAmountIncTax           = _purchaseOrderTmp.LineAmount * 1.1; // ****

        next insertOrderLine(_purchaseOrderTmp);
    }
